/// The family the table is read by: the run's REQUESTED family (its `w:rFonts` slot) when the face that draws it is that
/// family or its open metric twin (Arial → Liberation Sans, Calibri → Carlito, Cambria → Caladea, Times New Roman →
/// Liberation Serif, Courier New → Liberation Mono) — Word draws the requested font, the product its twin with the same
/// metrics, so the document gets Word's values either way; otherwise (a fallback face for another script) the drawn
/// family's own row, if any.
#[must_use]
pub fn table_family<'a>(requested: Option<&'a str>, drawn: &'a str) -> &'a str {
    if let Some(req) = requested
        && font_index(req).is_some()
    {
        let lower = uo_text::case::to_lowercase_str(req);
        let drawn_lower = uo_text::case::to_lowercase_str(drawn);
        let twin = uo_fonts::metric_substitute(lower.as_str()).map(uo_text::case::to_lowercase_str);
        if drawn_lower == lower || twin.as_deref() == Some(drawn_lower.as_str()) {
            return req;
        }
    }
    drawn
}

/// `(raise, drop, superscript size)` in points for a run of `base` points above 24 pt in a font of the table (`None`:
/// at or below 24 pt, a fraction of a half point, or another font — the frozen TS rules apply).
#[must_use]
pub fn word_sup_sub(family: &str, base: f64) -> Option<(f64, f64, f64)> {
    if base.is_nan() || base <= 24.0 {
        return None;
    }
    let f = font_index(family)?;
    let half = |v: u16| f64::from(v) / 2.0;
    if base <= 200.0 {
        let i = (base - 24.0) * 2.0;
        if i.fract() != 0.0 {
            return None;
        }
        #[expect(clippy::cast_possible_truncation, clippy::cast_sign_loss, reason = "0 ≤ i ≤ 352, integral")]
        let i = i as usize;
        return Some((half(*RAISE.get(f)?.get(i)?), half(*DROP.get(f)?.get(i)?), half(*SUP_SIZE.get(f)?.get(i)?)));
    }
    if let Some(k) = BIG.iter().position(|b| *b == base) {
        return Some((half(*BIG_RAISE.get(f)?.get(k)?), half(*BIG_DROP.get(f)?.get(k)?), half(*BIG_SUP_SIZE.get(f)?.get(k)?)));
    }
    let (r, d) = *RATIO.get(f)?;
    let round_half = |v: f64| uo_jsnum::math::floor(v * 2.0 + 0.5) / 2.0;
    // superscript size beyond 200 pt: Cambria's measured row is exactly 0.6 × the size (250 → 150 … 1000 → 600 pt), the
    // other nine fonts follow 1331/2048
    let size = if FONTS.get(f) == Some(&"cambria") {
        uo_jsnum::math::round(base * 2.0 * 0.6) / 2.0
    } else {
        uo_jsnum::math::round((base * 2.0 * 1331.0) / 2048.0) / 2.0
    };
    Some((round_half(r * base), round_half(d * base), size))
}
